<?php require_once 'header.php'; function ef($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); } $isEdit = !empty($record); ?>
<main class="content-body"><section class="page-section"><div class="section-title-bar"><div class="section-title"><i class="fa-solid fa-stethoscope"></i> <?php echo $isEdit ? 'Sửa số liệu khám ngoại trú' : 'Nhập số liệu khám ngoại trú'; ?></div><a href="<?php echo XC_URL; ?>/backend/outpatient" class="btn btn-outline"><i class="fa-solid fa-arrow-left"></i> Quay lại</a></div><?php if (!$isEdit): ?><div class="card" style="margin-bottom:18px"><div class="card-header"><div class="card-title"><i class="fa-solid fa-file-excel"></i> Import Excel/CSV</div><a href="<?php echo XC_URL; ?>/backend/outpatient/template" class="btn btn-outline btn-sm"><i class="fa-solid fa-download"></i> Tải file mẫu</a></div><div class="card-body"><form method="post" enctype="multipart/form-data" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?php echo ef($csrf); ?>"><input type="hidden" name="action" value="import"><input type="file" name="import_file" accept=".xlsx,.csv" required><span style="font-size:12px;color:var(--text-muted)">Cột bắt buộc: report_date, department_id, payer_type_id. Danh mục nằm trong file mẫu.</span><button class="btn btn-success">Import</button></form><?php if (!empty($flash['message'])): ?><p style="margin-top:12px;color:<?php echo $flash['type']==='success'?'var(--success)':'var(--danger)'; ?>"><?php echo ef($flash['message']); ?></p><?php endif; ?></div></div><?php endif; ?><div id="notice" style="display:none;margin-bottom:18px"></div><div class="card"><div class="card-body"><form id="outpatientForm" class="form-grid" novalidate><input type="hidden" name="csrf" value="<?php echo ef($csrf); ?>"><input type="hidden" name="id" value="<?php echo $isEdit ? (int)$record->id : ''; ?>"><div class="form-group"><label class="form-label">Ngày báo cáo <span class="req">*</span></label><input required class="form-control" type="date" name="report_date" value="<?php echo ef($isEdit ? substr($record->report_date,0,10) : date('Y-m-d')); ?>"></div><div class="form-group"><label class="form-label">Khoa/phòng <span class="req">*</span></label><select required class="form-select" name="department_id"><option value="">Chọn khoa/phòng</option><?php foreach($departments as $d): ?><option value="<?php echo $d->id; ?>" <?php echo $isEdit && $record->department_id==$d->id?'selected':''; ?>><?php echo ef($d->department_name); ?></option><?php endforeach; ?></select></div><div class="form-group"><label class="form-label">Đối tượng thanh toán <span class="req">*</span></label><select required class="form-select" name="payer_type_id"><option value="">Chọn đối tượng</option><?php foreach($payerTypes as $p): ?><option value="<?php echo $p->id; ?>" <?php echo $isEdit && $record->payer_type_id==$p->id?'selected':''; ?>><?php echo ef($p->payer_type_name); ?></option><?php endforeach; ?></select></div><?php foreach(array('visit_count'=>'Tổng lượt khám','revisit_count'=>'Lượt tái khám','waiting_count'=>'Đang chờ khám','examining_count'=>'Đang được khám','completed_count'=>'Đã hoàn thành','referral_count'=>'Chuyển tuyến') as $key=>$label): ?><div class="form-group"><label class="form-label"><?php echo $label; ?></label><input class="form-control" type="number" min="0" name="<?php echo $key; ?>" value="<?php echo $isEdit ? (int)$record->$key : 0; ?>"></div><?php endforeach; ?><div class="form-group"><label class="form-label">Thời gian chờ TB (phút)</label><input class="form-control" type="number" min="0" step="0.01" name="avg_wait_minutes" value="<?php echo $isEdit && $record->avg_wait_minutes !== null ? ef($record->avg_wait_minutes) : ''; ?>"></div><div class="form-actions" style="grid-column:1/-1"><a class="btn btn-outline" href="<?php echo XC_URL; ?>/backend/outpatient">Hủy</a><button class="btn btn-primary" id="saveButton"><i class="fa-solid fa-floppy-disk"></i> <?php echo $isEdit ? 'Cập nhật' : 'Lưu số liệu'; ?></button></div></form></div></div></section></main>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script>$('#outpatientForm').on('submit',function(e){e.preventDefault();const form=this;if(!form.checkValidity()){form.reportValidity();return}const button=$('#saveButton').prop('disabled',true);$.ajax({url:'<?php echo XC_URL; ?>/api/saveOutpatient',type:'POST',data:$(form).serialize(),dataType:'json'}).done(function(res){if(res.success){Swal.fire({icon:'success',title:'Thành công',text:res.message,toast:true,position:'top-end',showConfirmButton:false,timer:1400,timerProgressBar:true}).then(()=>location.href='<?php echo XC_URL; ?>/backend/outpatient')}else{Swal.fire({icon:'error',title:'Không thể lưu',text:res.message,confirmButtonText:'Đã hiểu'});button.prop('disabled',false)}}).fail(function(xhr){let message='Máy chủ không thể xử lý yêu cầu. Vui lòng thử lại.';if(xhr.responseJSON&&xhr.responseJSON.message)message=xhr.responseJSON.message;Swal.fire({icon:'error',title:'Lưu dữ liệu thất bại',text:message,confirmButtonText:'Đã hiểu'});button.prop('disabled',false)})})</script>
